function addTranslations(
  sources: readonly string[],
  values: { sv: readonly string[]; es: readonly string[]; de: readonly string[]; fa: readonly string[]; ar: readonly string[] },
) {
  for (const locale of ['sv', 'es', 'de', 'fa', 'ar'] as const) {
    if (values[locale].length !== sources.length) {
      throw new Error(`Dashboard translation count mismatch for ${locale}: expected ${sources.length}, received ${values[locale].length}`);
    }
  }
  sources.forEach((source, index) => {
    sv[source] = values.sv[index];
    es[source] = values.es[index];
    de[source] = values.de[index];
    fa[source] = values.fa[index];
    ar[source] = values.ar[index];
  });
}

