export const DASHBOARD_TRANSLATION_KEYS = Object.freeze(Object.keys(sv).sort());
const en = Object.fromEntries(DASHBOARD_TRANSLATION_KEYS.map((key) => [key, key]));
const dictionaries: Record<DashboardLocale, Record<string, string>> = { en, sv, es, de, fa, ar };
const localeTags: Record<DashboardLocale, string> = { en: 'en-GB', sv: 'sv-SE', es: 'es-ES', de: 'de-DE', fa: 'fa-IR', ar: 'ar' };

export function missingDashboardTranslationKeys(locale: DashboardLocale): string[] {
  return DASHBOARD_TRANSLATION_KEYS.filter((key) => !dictionaries[locale][key]);
}

export function isDashboardLocale(value: unknown): value is DashboardLocale {
  return typeof value === 'string' && DASHBOARD_LOCALES.includes(value as DashboardLocale);
}

export function resolveDashboardLocale(stored?: string | null, browserLocales: readonly string[] = []): DashboardLocale {
  if (isDashboardLocale(stored)) return stored;
  for (const value of browserLocales) {
    const base = value.toLowerCase().split('-')[0];
    if (isDashboardLocale(base)) return base;
  }
  return 'en';
}

export function dashboardDirection(locale: DashboardLocale): 'ltr' | 'rtl' {
  return locale === 'fa' || locale === 'ar' ? 'rtl' : 'ltr';
}

export function persistDashboardLocale(storage: Pick<Storage, 'setItem'>, locale: DashboardLocale): DashboardLocale {
  const safe = resolveDashboardLocale(locale);
  storage.setItem(DASHBOARD_LOCALE_STORAGE_KEY, safe);
  return safe;
}

type DashboardInterpolationValues = Readonly<Record<string, string | number>>;

function interpolateDashboardText(locale: DashboardLocale, template: string, values: DashboardInterpolationValues): string {
  return template.replace(/\{([a-zA-Z][a-zA-Z0-9]*)\}/g, (_match, name: string) => {
    const value = values[name];
    if (value === undefined) return `{${name}}`;
    const rendered = typeof value === 'number' || /^-?\d+(?:\.\d+)?$/.test(String(value))
      ? formatDashboardNumber(locale, Number(value))
      : String(value);
    return dashboardDirection(locale) === 'rtl' ? `\u2068${rendered}\u2069` : rendered;
  });
}

function templateValues(template: string, source: string): DashboardInterpolationValues | null {
  const names: string[] = [];
  const expression = template
    .split(/(\{[a-zA-Z][a-zA-Z0-9]*\})/g)
    .map((part) => {
      const match = part.match(/^\{([a-zA-Z][a-zA-Z0-9]*)\}$/);
      if (match) {
        names.push(match[1]);
        return '(.+?)';
      }
      return part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    })
    .join('');
  const match = source.match(new RegExp(`^${expression}$`));
  if (!match) return null;
  return Object.fromEntries(names.map((name, index) => [name, match[index + 1]]));
}

export function translateDashboardText(locale: DashboardLocale, source: string, values?: DashboardInterpolationValues): string {
  const leading = source.match(/^\s*/)?.[0] || '';
  const trailing = source.match(/\s*$/)?.[0] || '';
  const core = source.trim();
  if (!core) return source;
  const translated = dictionaries[locale][core];
  if (translated) return `${leading}${interpolateDashboardText(locale, translated, values || {})}${trailing}`;
  if (!values) {
    for (const key of DASHBOARD_TRANSLATION_KEYS) {
      if (!key.includes('{')) continue;
      const matchedValues = templateValues(key, core);
      if (matchedValues) return `${leading}${interpolateDashboardText(locale, dictionaries[locale][key], matchedValues)}${trailing}`;
    }
  }
  return source;
}

function canonicalDashboardText(value: string): string {
  const leading = value.match(/^\s*/)?.[0] || '';
  const trailing = value.match(/\s*$/)?.[0] || '';
  const core = value.trim();
  for (const locale of DASHBOARD_LOCALES) {
    for (const [source, translated] of Object.entries(dictionaries[locale])) {
      if (translated === core) return `${leading}${source}${trailing}`;
    }
  }
  return value;
}

export function formatDashboardNumber(locale: DashboardLocale, value: number, options?: Intl.NumberFormatOptions): string {
  return new Intl.NumberFormat(localeTags[locale], options).format(value);
}

export function formatDashboardDate(locale: DashboardLocale, value: Date | string | number, options?: Intl.DateTimeFormatOptions): string {
  return new Intl.DateTimeFormat(localeTags[locale], options).format(new Date(value));
}

interface DashboardI18nValue {
  locale: DashboardLocale;
  direction: 'ltr' | 'rtl';
  setLocale: (locale: DashboardLocale) => void;
  t: (source: string, values?: DashboardInterpolationValues) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: Date | string | number, options?: Intl.DateTimeFormatOptions) => string;
}

const defaultValue: DashboardI18nValue = {
  locale: 'en', direction: 'ltr', setLocale: () => undefined,
  t: (source, values) => translateDashboardText('en', source, values),
  formatNumber: (value, options) => formatDashboardNumber('en', value, options),
  formatDate: (value, options) => formatDashboardDate('en', value, options),
};

const DashboardI18nContext = createContext<DashboardI18nValue>(defaultValue);

export function DashboardI18nProvider({ children, storage = typeof window === 'undefined' ? undefined : window.localStorage }: { children: ReactNode; storage?: Pick<Storage, 'getItem' | 'setItem'> }) {
  const [locale, setLocaleState] = useState<DashboardLocale>(() => resolveDashboardLocale(
    storage?.getItem(DASHBOARD_LOCALE_STORAGE_KEY),
    typeof navigator === 'undefined' ? [] : navigator.languages,
  ));
  const setLocale = useCallback((next: DashboardLocale) => {
    const safe = resolveDashboardLocale(next);
    setLocaleState(safe);
    if (storage) persistDashboardLocale(storage, safe);
  }, [storage]);
  const value = useMemo<DashboardI18nValue>(() => ({
    locale,
    direction: dashboardDirection(locale),
    setLocale,
    t: (source, values) => translateDashboardText(locale, source, values),
    formatNumber: (number, options) => formatDashboardNumber(locale, number, options),
    formatDate: (date, options) => formatDashboardDate(locale, date, options),
  }), [locale, setLocale]);
  return <DashboardI18nContext.Provider value={value}>{children}</DashboardI18nContext.Provider>;
}

export function useDashboardI18n() {
  return useContext(DashboardI18nContext);
}

export function localizeDashboardDom(root: HTMLElement, locale: DashboardLocale): () => void {
  const originals = new WeakMap<Node, string>();
  const attributeOriginals = new WeakMap<Element, Map<string, string>>();
  let applying = false;
  const skip = (element: Element | null) => Boolean(element?.closest('[translate="no"], .mono, .transcript-bubble, .conversation-title, .biz-name'));
  const applyNode = (node: Node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      if (skip(node.parentElement)) return;
      const current = node.textContent || '';
      const prior = originals.get(node);
      const expected = prior === undefined ? undefined : translateDashboardText(locale, prior);
      if (prior === undefined || (current !== expected && current === canonicalDashboardText(current))) originals.set(node, canonicalDashboardText(current));
      const source = originals.get(node) || '';
      const next = translateDashboardText(locale, source);
      if (current !== next) node.textContent = next;
      return;
    }
    if (!(node instanceof Element) || skip(node)) return;
    const attrs = ['aria-label', 'title', 'placeholder'];
    let saved = attributeOriginals.get(node);
    if (!saved) { saved = new Map(); attributeOriginals.set(node, saved); }
    for (const attr of attrs) {
      const current = node.getAttribute(attr);
      if (current === null) continue;
      const prior = saved.get(attr);
      const expected = prior === undefined ? undefined : translateDashboardText(locale, prior);
      if (prior === undefined || (current !== expected && current === canonicalDashboardText(current))) saved.set(attr, canonicalDashboardText(current));
      const next = translateDashboardText(locale, saved.get(attr) || '');
      if (current !== next) node.setAttribute(attr, next);
    }
    for (const child of Array.from(node.childNodes)) applyNode(child);
  };
  const apply = (node: Node) => { applying = true; applyNode(node); applying = false; };
  apply(root);
  const observer = new MutationObserver((mutations) => {
    if (applying) return;
    for (const mutation of mutations) {
      if (mutation.type === 'characterData') apply(mutation.target);
      else if (mutation.type === 'attributes') apply(mutation.target);
      else for (const node of Array.from(mutation.addedNodes)) apply(node);
    }
  });
  observer.observe(root, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['aria-label', 'title', 'placeholder'] });
  return () => observer.disconnect();
}
